package handler
import("encoding/json";"net/http";"strconv";"github.com/go-chi/chi/v5";"go-repair-center/internal/service";"go-repair-center/internal/transport/http/dto";"go-repair-center/internal/transport/http/middleware";"go-repair-center/internal/transport/http/response")
type PartHandler struct{*GenericHandler;parts *service.PartService}
func NewPartHandler(parts *service.PartService)*PartHandler{return &PartHandler{GenericHandler:NewGenericHandler(parts,"part"),parts:parts}}
func(h *PartHandler)Routes(router chi.Router){router.Route("/parts",func(resource chi.Router){h.Register(resource,"part:read","part:write");resource.With(middleware.Require("part:write")).Post("/usage",h.Use);resource.With(middleware.Require("part:write")).Put("/{id}/adjust",h.Adjust)})}
func(h *PartHandler)Use(w http.ResponseWriter,r *http.Request){var input dto.StockUsageRequest;if err:=json.NewDecoder(r.Body).Decode(&input);err!=nil{writeError(w,r,err);return};record,err:=h.parts.Use(r.Context(),input.PartID,input.Quantity,input.RepairExecutionID,middleware.UserID(r.Context()),r.Header.Get("Idempotency-Key"));if err!=nil{writeError(w,r,err);return};response.Created(w,record,middleware.RequestID(r.Context()))}
func(h *PartHandler)Adjust(w http.ResponseWriter,r *http.Request){id,_:=strconv.ParseInt(chi.URLParam(r,"id"),10,64);var input dto.StockAdjustmentRequest;if err:=json.NewDecoder(r.Body).Decode(&input);err!=nil{writeError(w,r,err);return};record,err:=h.parts.Adjust(r.Context(),id,input.Delta,input.Reason,middleware.UserID(r.Context()));if err!=nil{writeError(w,r,err);return};response.Success(w,record,middleware.RequestID(r.Context()))}
